CREATE TABLE invoice_settings(company_id TEXT PRIMARY KEY REFERENCES companies(id), name TEXT NOT NULL, address TEXT NOT NULL, cvr TEXT NOT NULL, contact TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, logo_key TEXT, months INTEGER NOT NULL DEFAULT 3 CHECK(months BETWEEN 1 AND 120));
CREATE TABLE invoice_orders(company_id TEXT NOT NULL,webshop_id TEXT NOT NULL,external_id TEXT NOT NULL,name TEXT NOT NULL,created_at TEXT NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(company_id,webshop_id,external_id),FOREIGN KEY(company_id,webshop_id) REFERENCES webshops(company_id,id));
CREATE TABLE platform_invoices(company_id TEXT NOT NULL,webshop_id TEXT NOT NULL,external_id TEXT NOT NULL,id TEXT NOT NULL UNIQUE, fingerprint TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('generating','generated')),r2_key TEXT NOT NULL,issuer_json TEXT NOT NULL,source_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(company_id,webshop_id,external_id),FOREIGN KEY(company_id,webshop_id) REFERENCES webshops(company_id,id));
